type Rectangle struct {
	Width, Height int
}

func (r Rectangle) Area() int { // value receiver: read-only
	return r.Width * r.Height
}

func (r *Rectangle) Scale(factor int) { // pointer receiver: mutates
	r.Width *= factor
	r.Height *= factor
}
